  const { people, claims, today } = useSheetData(sheetId);
  const ids = patronIdsOf(useQuery(patronsQuery(sheetId)).data ?? [], personId);
  const sums = people.filter((p) => ids.includes(p.id)).map((p) => recentSettled(p.id, claims, today));
